// Broker-side idempotent dedup: last accepted sequence per (producer-ID, partition).
function broker() {
  const lastSeq = new Map();          // "pid:partition" -> last accepted sequence
  return function deliver(pid, partition, seq) {
    const key = pid + ":" + partition;
    const last = lastSeq.has(key) ? lastSeq.get(key) : -1;
    if (seq === last + 1) { lastSeq.set(key, seq); return "ACCEPT"; }
    if (seq <= last)      { return "DUPLICATE"; }   // retry of an already-seen write
    return "OUT_OF_ORDER";                          // forward gap -> rejected
  };
}

const deliver = broker();
const events = [
  [7, 0, 0],
  [7, 0, 1],
  [7, 0, 2],
  [7, 0, 2],   // retry: the ack was dropped on the network
  [7, 0, 3],
  [7, 0, 1],   // late retry of an old write
];
let accepted = 0, deduped = 0;
for (const [pid, part, seq] of events) {
  const r = deliver(pid, part, seq);
  if (r === "ACCEPT") accepted++;
  if (r === "DUPLICATE") deduped++;
  console.log("seq=" + seq + " -> " + r);
}
console.log("accepted=" + accepted + " deduped=" + deduped);
